<div x-data="{
    total: {{ count($selected) }},
    recount() { this.total = document.querySelectorAll('input[name=\'permissions[]\']:checked').length; },
    allChecked(prefix) {
        const boxes = document.querySelectorAll('input[data-group=\'' + prefix + '\']');
        return boxes.length > 0 && Array.from(boxes).every(b => b.checked);
    },
    toggleGroup(prefix, checked) {
        document.querySelectorAll('input[data-group=\'' + prefix + '\']').forEach(b => b.checked = checked);
        this.recount();
    },
}">
    <div class="mb-4 flex items-center justify-between rounded-lg border border-brass/15 bg-brass-soft/40 px-4 py-3">
        <p class="text-sm text-ink">إجمالي الصلاحيات المحددة</p>
        <p class="font-display text-lg font-semibold text-brass">
